});

test('lineDiscount calculates discount correctly', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 9500, discountPercent: 20 }), 19000);
});

test('lineDiscount with 0% discount returns 0', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 9500, discountPercent: 0 }), 0);
});

test('lineDiscount with 100% discount equals lineTotal', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 9500, discountPercent: 100 }), 95000);
});

test('lineDiscount defaults to 0% if discountPercent is undefined', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 9500 }), 0);
});

test('lineDiscount with decimal discount rounds correctly', () => {
  assert.equal(lineDiscount({ qty: 1, unitPrice: 1000, discountPercent: 33.33 }), 333);
});

test('invoiceTotals includes discount field', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500, discountPercent: 20 },
    ],
  };

  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 19000);
  assert.equal(totals.total, 76000);
});

test('invoiceTotals with multiple lines sums discounts', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500, discountPercent: 20 },
      { qty: 5, unitPrice: 8500, discountPercent: 10 },
    ],
  };

  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 95000 + 42500);
  assert.equal(totals.discount, 19000 + 4250);
  assert.equal(totals.total, 137500 - 23250);
});

test('invoiceTotals clamps total to 0 if discount exceeds subtotal', () => {
