  assert.equal(r2.value.lines[1].discountPercent, 15);
});

test('addLine defaults discountPercent to 0', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const r2 = addLine(r1.value, { sku: 'DES-HOUR', qty: 5 });

