    { ok: false, error: 'DISCOUNT_INVALID' }
  );
});

test('invoiceTotals on a created invoice with discounts', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'DES-HOUR', qty: 5, discountPercent: 0 },
    ],
  });

