        { sku: 'DEV-HOUR', qty: 1 },
        { sku: 'UNKNOWN', qty: 1 },
      ],
    }),
    { ok: false, error: 'UNKNOWN_SKU' }
  );
});

test('createInvoice does not mutate the input', () => {
  const input = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  };
  const inputCopy = JSON.parse(JSON.stringify(input));

  createInvoice(input);

  assert.deepEqual(input, inputCopy);
});

test('lineTotal calculates qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 10, unitPrice: 9500 }), 95000);
  assert.equal(lineTotal({ qty: 5, unitPrice: 8500 }), 42500);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
});

test('lineTotal handles single quantity', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 6000 }), 6000);
});

test('lineTotal handles zero unitPrice', () => {
  assert.equal(lineTotal({ qty: 10, unitPrice: 0 }), 0);
});

test('invoiceTotals sums the line totals', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500 },
      { qty: 5, unitPrice: 8500 },
    ],
  };

  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 95000 + 42500);
  assert.equal(totals.total, 95000 + 42500);
});

test('invoiceTotals with a single line', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 9500 }],
  };

  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.total, 95000);
});

test('invoiceTotals with three lines', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500 },
      { qty: 5, unitPrice: 8500 },
      { qty: 2, unitPrice: 120000 },
    ],
  };

  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 95000 + 42500 + 240000);
  assert.equal(totals.total, 95000 + 42500 + 240000);
});

test('invoiceTotals with zero lines', () => {
  const invoice = {
    lines: [],
  };

  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals on a created invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'DES-HOUR', qty: 5 },
    ],
  });

  const totals = invoiceTotals(r.value);

  assert.equal(totals.subtotal, 10 * 9500 + 5 * 8500);
  assert.equal(totals.total, 10 * 9500 + 5 * 8500);
});

test('addLine adds a new line to an invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const r2 = addLine(r1.value, { sku: 'DES-HOUR', qty: 5 });

  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 2);
