});

test('invoiceTotals sums the line totals', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500 },
      { qty: 5, unitPrice: 8500 },
    ],
  };

  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 95000 + 42500);
  assert.equal(totals.total, 95000 + 42500);
});

test('invoiceTotals with a single line', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 9500 }],
  };

  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.total, 95000);
});

test('invoiceTotals with three lines', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500 },
      { qty: 5, unitPrice: 8500 },
      { qty: 2, unitPrice: 120000 },
    ],
  };

  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 95000 + 42500 + 240000);
  assert.equal(totals.total, 95000 + 42500 + 240000);
});

